def max_sum_increasing_subsequence(arr, n):
    # Initialize a list to store the maximum sum of increasing subsequences ending at each index
    dp = [0] * n

    # Base case: the sum of a single element is the element itself
    for i in range(n):
        dp[i] = arr[i]

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    # The maximum sum in the last row of dp array is the answer
    return dp[n-1]

