def find_kth(nums1, nums2, k, i, j):
    # Base case: if k is 0, return the last element of nums1
    if k == 0:
        return nums1[i]

    # Check if k is greater than the length of nums1 or nums2
    if k > len(nums1) + len(nums2):
        return None

    # Calculate the middle index
    mid = i + (j - i) // 2

    # Compare the middle element with k
    if nums1[mid] == k:
        return nums1[mid]
    elif nums1[mid] < k:
        # If the middle element is less than k, search in the right half
        return find_kth(nums1[mid + 1:], nums2, k - mid - 1, i + mid + 1, j)
    else:
        # If the middle element is greater than k, search in the left half
        return find_kth(nums1, nums2[:mid], k - mid, i, mid - 1)

