def count_Fac(num):
    # Initialize a set to store distinct power of prime factors
    distinct_factors = set()
    # Divide num by 2 to remove all even factors
    while num % 2 == 0:
        distinct_factors.add(2)
        num //= 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(num**0.5) + 1, 2):
        # While i divides num, add i and divide num
        while num % i == 0:
            distinct_factors.add(i)
            num //= i
    # If num is a prime number greater than 2
    if num > 2:
        distinct_factors.add(num)
    return len(distinct_factors)

