    # Initialize DP array
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Fill the DP array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1] == str3[k - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
