def generate_matrix(n):
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    current_element = 1
    row, col = 0, 0
    direction = 0  # 0 -> right, 1 -> down, 2 -> left, 3 -> up

    while current_element <= n*n:
        matrix[row][col] = current_element
        current_element += 1

        if direction == 0:
            col += 1
            if col == n:
                direction = 1  # Move down
                row += 1
        elif direction == 1:
            row += 1
            if row == n:
                direction = 2  # Move left
                col -= 1
        elif direction == 2:
            col -= 1
            if col == -1:
                direction = 3  # Move up
                row -= 1
        else:
            row -= 1
            if row == -1:
                direction = 0  # Move right

    return matrix

