def super_seq(str1, str2, m, n):
    # Create a DP array to store the length of the shortest common supersequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                # If either string is empty, the shortest supersequence is 0
                dp[i][j] = 0
            elif str1[i - 1] == str2[j - 1]:
                # If the characters match, the length is one more than the length of the common prefix
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                # If the characters do not match, the length is the maximum of the lengths of the two strings
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the shortest common supersequence
    return dp[m][n]

