def max_char(input_string):
    # Initialize a dictionary to count character frequencies
    char_count = {}

    # Iterate over each character in the input string
    for char in input_string:
        # Increment the count for the current character
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum frequency
    max_freq = max(char_count.values())

    # Initialize an empty list to store the most common characters
    common_chars = []

    # Collect all characters with the maximum frequency
    for char, freq in char_count.items():
        if freq == max_freq:
            common_chars.append(char)

    # Return the most common character(s)
    return common_chars

