def most_common_elem(text, n):
    # Split the text into words
    words = text.split()
    # Count the occurrences of each word
    count = {}
    for word in words:
        if word in count:
            count[word] += 1
        else:
            count[word] = 1
    # Find the most common elements
    most_common = sorted(count.items(), key=lambda x: x[1], reverse=True)
    # Return the top n elements
    return most_common[:n]
