def min_sum_path(triangle):
    # Iterate through each row in the triangle
    for i in range(len(triangle)):
        # Iterate through each element in the current row
        for j in range(i):
            # If the current element is less than the sum of the two adjacent elements,
            # update the current element with the sum of the two adjacent elements
            if triangle[i][j] < triangle[i][j + 1] + triangle[i + 1][j]:
                triangle[i][j] += triangle[i][j + 1] + triangle[i + 1][j]
    # Return the minimum value in the triangle
    return min(triangle[-1])
